<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { dApi, type Seat } from '../api';
import { errorMessage } from '../../../shared/api/client';
import RequestState from '../../../shared/components/RequestState.vue';
const props = defineProps<{ roomId: string; retired: boolean }>();
const seats = ref<Seat[]>([]); const loading = ref(false); const error = ref(''); const actionError = ref(''); const message = ref(''); const busy = ref(false); const editing = ref<string | null>(null); const confirmRetire = ref<string | null>(null);
const form = reactive({ number: '', hasSocket: false, active: true });
async function load() { loading.value = true; error.value = ''; try { seats.value = (await dApi.seats(props.roomId)).items; } catch (cause) { error.value = errorMessage(cause); } finally { loading.value = false; } }
onMounted(load);
function edit(seat: Seat) { editing.value = seat.id; form.number = seat.number; form.hasSocket = seat.hasSocket; form.active = seat.active; actionError.value = ''; message.value = ''; document.getElementById('seat-number')?.focus(); }
function reset() { editing.value = null; form.number = ''; form.hasSocket = false; form.active = true; }
async function save() { if (busy.value) return; busy.value = true; actionError.value = ''; message.value = ''; try { if (editing.value) await dApi.updateSeat(editing.value, { ...form }); else await dApi.createSeat(props.roomId, { ...form }); message.value = editing.value ? '座位信息已保存。' : '座位已登记。'; reset(); await load(); } catch (cause) { actionError.value = `${errorMessage(cause)} 如果创建结果不确定，请先刷新座位列表核对，勿直接重复创建。`; } finally { busy.value = false; } }
async function retire(id: string) { busy.value = true; actionError.value = ''; try { await dApi.retireSeat(id); confirmRetire.value = null; if (editing.value === id) reset(); await load(); } catch (cause) { actionError.value = errorMessage(cause); } finally { busy.value = false; } }
</script>
<template><section><h2>座位目录</h2><p class="feature-note">编号在本房间内唯一，注销后仍保留编号和历史引用。停用可以恢复；注销不可恢复。</p><RequestState :loading="loading" :error="error" :empty="!seats.length" empty-text="这个房间还没有座位" @retry="load" /><p v-if="actionError" class="feature-error" role="alert">{{ actionError }}</p><p v-if="message" class="feature-success" role="status">{{ message }}</p><div v-if="!loading && !error" class="feature-list"><article v-for="seat in seats" :key="seat.id" class="feature-panel ui-panel"><div class="feature-row"><div><h3>{{ seat.number }} 号座位</h3><p>{{ seat.hasSocket ? '配有插座' : '无插座' }} · {{ seat.retired ? '已注销' : seat.active ? '可使用' : '已停用' }}</p></div><div v-if="!seat.retired && !retired" class="seat-actions"><button type="button" class="ui-button" :disabled="busy" @click="edit(seat)">编辑</button><button type="button" class="ui-button" :disabled="busy" @click="confirmRetire = seat.id">注销</button></div></div><div v-if="confirmRetire === seat.id" class="retire-confirm"><p>确认永久注销 {{ seat.number }} 号座位？需要临时暂停请使用“编辑 → 停用”。</p><div class="feature-actions"><button type="button" class="ui-button" :disabled="busy" @click="retire(seat.id)">确认注销</button><button type="button" class="ui-button" :disabled="busy" @click="confirmRetire = null">返回</button></div></div></article></div><form v-if="!retired" class="feature-panel ui-panel seat-form" @submit.prevent="save"><h3>{{ editing ? '编辑座位' : '登记座位' }}</h3><fieldset :disabled="busy"><label class="feature-field" for="seat-number">座位编号<input id="seat-number" v-model="form.number" required maxlength="40" /></label><div class="feature-actions"><label class="feature-check"><input v-model="form.hasSocket" type="checkbox" />配有插座</label><label class="feature-check"><input v-model="form.active" type="checkbox" />启用座位</label></div></fieldset><div class="feature-actions"><button class="ui-button ui-button--primary" :disabled="busy">{{ busy ? '正在保存…' : editing ? '保存修改' : '登记座位' }}</button><button v-if="editing" type="button" class="ui-button" :disabled="busy" @click="reset">取消编辑</button></div></form></section></template>
<style scoped src="../../../shared/styles/feature.css"></style><style scoped>.seat-actions{display:flex;gap:8px;flex-wrap:wrap}.seat-form{margin-top:22px}.retire-confirm{margin-top:18px;border-top:1px solid var(--color-border);padding-top:18px;font-size:13px}h3{margin-bottom:5px}fieldset{border:0;padding:0;margin:0;min-width:0}</style>
